{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this analysis — are we maximizing the total value of exports (i.e., the value of domestically produced goods sold on the world market), or is there a different goal such as maximizing net trade balance or minimizing imports?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "How is domestic GDP measured in this model — is it the total value of all four domestically produced goods (steel, engines, electronics, plastic) at their world-market prices, or does it exclude some categories (for example, treating imported goods or intermediate inputs differently)?"
  ],
  "rationale": "The response contains a single clarification question asking for the specific definition or calculation method of domestic GDP, presenting two alternative interpretations as part of one policy choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the four listed products (steel, engines, electronics, plastic) the only goods produced and traded in this model, or are there other goods whose production or trade should also be included?"
  ],
  "rationale": "The response contains a single clarification question asking whether the product list is exhaustive or if additional goods should be included."
}

